    const auto& f_n_nodes = rData.BodySourceOld1;
    const auto& f_nn_nodes = rData.BodySourceOld2;

    // Assemble RHS contribution
    const double w_g = rData.Weight;

        const double crRightHandSideVector0 = beta0_gauss*(N_p1[0]*p_nn_nodes[0] + N_p1[1]*p_nn_nodes[1] + N_p1[2]*p_nn_nodes[2] + N_p1[3]*p_nn_nodes[3]) + beta1_gauss*(N_p1[0]*p_n_nodes[0] + N_p1[1]*p_n_nodes[1] + N_p1[2]*p_n_nodes[2] + N_p1[3]*p_n_nodes[3]) + beta2_gauss*(N_p1[0]*p_nodes[0] + N_p1[1]*p_nodes[1] + N_p1[2]*p_nodes[2] + N_p1[3]*p_nodes[3]);
    const double crRightHandSideVector1 = N_p2[0]*u_nn_nodes(0,0) + N_p2[1]*u_nn_nodes(1,0) + N_p2[2]*u_nn_nodes(2,0) + N_p2[3]*u_nn_nodes(3,0) + N_p2[4]*u_nn_nodes(4,0) + N_p2[5]*u_nn_nodes(5,0) + N_p2[6]*u_nn_nodes(6,0) + N_p2[7]*u_nn_nodes(7,0) + N_p2[8]*u_nn_nodes(8,0) + N_p2[9]*u_nn_nodes(9,0);
    const double crRightHandSideVector2 = N_p2[0]*u_n_nodes(0,0) + N_p2[1]*u_n_nodes(1,0) + N_p2[2]*u_n_nodes(2,0) + N_p2[3]*u_n_nodes(3,0) + N_p2[4]*u_n_nodes(4,0) + N_p2[5]*u_n_nodes(5,0) + N_p2[6]*u_n_nodes(6,0) + N_p2[7]*u_n_nodes(7,0) + N_p2[8]*u_n_nodes(8,0) + N_p2[9]*u_n_nodes(9,0);
    const double crRightHandSideVector3 = N_p2[0]*u_nodes(0,0) + N_p2[1]*u_nodes(1,0) + N_p2[2]*u_nodes(2,0) + N_p2[3]*u_nodes(3,0) + N_p2[4]*u_nodes(4,0) + N_p2[5]*u_nodes(5,0) + N_p2[6]*u_nodes(6,0) + N_p2[7]*u_nodes(7,0) + N_p2[8]*u_nodes(8,0) + N_p2[9]*u_nodes(9,0);
    const double crRightHandSideVector4 = beta0_gauss*crRightHandSideVector1 + beta1_gauss*crRightHandSideVector2 + beta2_gauss*crRightHandSideVector3;
