    const double crRightHandSideVector10 = N_p2[0]*T_n_nodes[0] + N_p2[1]*T_n_nodes[1] + N_p2[2]*T_n_nodes[2] + N_p2[3]*T_n_nodes[3] + N_p2[4]*T_n_nodes[4] + N_p2[5]*T_n_nodes[5] + N_p2[6]*T_n_nodes[6] + N_p2[7]*T_n_nodes[7] + N_p2[8]*T_n_nodes[8] + N_p2[9]*T_n_nodes[9];
