    const double crRightHandSideVector12 = beta0_gauss*crRightHandSideVector9 + beta1_gauss*crRightHandSideVector10 + beta2_gauss*crRightHandSideVector11;
    const double crRightHandSideVector13 = crRightHandSideVector12*sigma_gauss;
    const double crRightHandSideVector14 = N_p2[0]*crRightHandSideVector13;
    const double crRightHandSideVector15 = DN_p2(0,0)*w_nodes(0,0) + DN_p2(1,0)*w_nodes(1,0) + DN_p2(2,0)*w_nodes(2,0) + DN_p2(3,0)*w_nodes(3,0) + DN_p2(4,0)*w_nodes(4,0) + DN_p2(5,0)*w_nodes(5,0) + DN_p2(6,0)*w_nodes(6,0) + DN_p2(7,0)*w_nodes(7,0) + DN_p2(8,0)*w_nodes(8,0) + DN_p2(9,0)*w_nodes(9,0);
