    const double crRightHandSideVector17 = beta0_gauss*(DN_p2(0,1)*w_nn_nodes(0,0) + DN_p2(1,1)*w_nn_nodes(1,0) + DN_p2(2,1)*w_nn_nodes(2,0) + DN_p2(3,1)*w_nn_nodes(3,0) + DN_p2(4,1)*w_nn_nodes(4,0) + DN_p2(5,1)*w_nn_nodes(5,0) + DN_p2(6,1)*w_nn_nodes(6,0) + DN_p2(7,1)*w_nn_nodes(7,0) + DN_p2(8,1)*w_nn_nodes(8,0) + DN_p2(9,1)*w_nn_nodes(9,0)) + beta1_gauss*(DN_p2(0,1)*w_n_nodes(0,0) + DN_p2(1,1)*w_n_nodes(1,0) + DN_p2(2,1)*w_n_nodes(2,0) + DN_p2(3,1)*w_n_nodes(3,0) + DN_p2(4,1)*w_n_nodes(4,0) + DN_p2(5,1)*w_n_nodes(5,0) + DN_p2(6,1)*w_n_nodes(6,0) + DN_p2(7,1)*w_n_nodes(7,0) + DN_p2(8,1)*w_n_nodes(8,0) + DN_p2(9,1)*w_n_nodes(9,0)) + beta2_gauss*(DN_p2(0,1)*w_nodes(0,0) + DN_p2(1,1)*w_nodes(1,0) + DN_p2(2,1)*w_nodes(2,0) + DN_p2(3,1)*w_nodes(3,0) + DN_p2(4,1)*w_nodes(4,0) + DN_p2(5,1)*w_nodes(5,0) + DN_p2(6,1)*w_nodes(6,0) + DN_p2(7,1)*w_nodes(7,0) + DN_p2(8,1)*w_nodes(8,0) + DN_p2(9,1)*w_nodes(9,0));
    const double crRightHandSideVector18 = beta0_gauss*(DN_p2(0,2)*w_nn_nodes(0,0) + DN_p2(1,2)*w_nn_nodes(1,0) + DN_p2(2,2)*w_nn_nodes(2,0) + DN_p2(3,2)*w_nn_nodes(3,0) + DN_p2(4,2)*w_nn_nodes(4,0) + DN_p2(5,2)*w_nn_nodes(5,0) + DN_p2(6,2)*w_nn_nodes(6,0) + DN_p2(7,2)*w_nn_nodes(7,0) + DN_p2(8,2)*w_nn_nodes(8,0) + DN_p2(9,2)*w_nn_nodes(9,0)) + beta1_gauss*(DN_p2(0,2)*w_n_nodes(0,0) + DN_p2(1,2)*w_n_nodes(1,0) + DN_p2(2,2)*w_n_nodes(2,0) + DN_p2(3,2)*w_n_nodes(3,0) + DN_p2(4,2)*w_n_nodes(4,0) + DN_p2(5,2)*w_n_nodes(5,0) + DN_p2(6,2)*w_n_nodes(6,0) + DN_p2(7,2)*w_n_nodes(7,0) + DN_p2(8,2)*w_n_nodes(8,0) + DN_p2(9,2)*w_n_nodes(9,0)) + beta2_gauss*(DN_p2(0,2)*w_nodes(0,0) + DN_p2(1,2)*w_nodes(1,0) + DN_p2(2,2)*w_nodes(2,0) + DN_p2(3,2)*w_nodes(3,0) + DN_p2(4,2)*w_nodes(4,0) + DN_p2(5,2)*w_nodes(5,0) + DN_p2(6,2)*w_nodes(6,0) + DN_p2(7,2)*w_nodes(7,0) + DN_p2(8,2)*w_nodes(8,0) + DN_p2(9,2)*w_nodes(9,0));
    const double crRightHandSideVector19 = DN_p2(0,0)*u_nodes(0,0) + DN_p2(1,0)*u_nodes(1,0) + DN_p2(2,0)*u_nodes(2,0) + DN_p2(3,0)*u_nodes(3,0) + DN_p2(4,0)*u_nodes(4,0) + DN_p2(5,0)*u_nodes(5,0) + DN_p2(6,0)*u_nodes(6,0) + DN_p2(7,0)*u_nodes(7,0) + DN_p2(8,0)*u_nodes(8,0) + DN_p2(9,0)*u_nodes(9,0);
    const double crRightHandSideVector20 = beta0_gauss*(DN_p2(0,0)*u_nn_nodes(0,0) + DN_p2(1,0)*u_nn_nodes(1,0) + DN_p2(2,0)*u_nn_nodes(2,0) + DN_p2(3,0)*u_nn_nodes(3,0) + DN_p2(4,0)*u_nn_nodes(4,0) + DN_p2(5,0)*u_nn_nodes(5,0) + DN_p2(6,0)*u_nn_nodes(6,0) + DN_p2(7,0)*u_nn_nodes(7,0) + DN_p2(8,0)*u_nn_nodes(8,0) + DN_p2(9,0)*u_nn_nodes(9,0)) + beta1_gauss*(DN_p2(0,0)*u_n_nodes(0,0) + DN_p2(1,0)*u_n_nodes(1,0) + DN_p2(2,0)*u_n_nodes(2,0) + DN_p2(3,0)*u_n_nodes(3,0) + DN_p2(4,0)*u_n_nodes(4,0) + DN_p2(5,0)*u_n_nodes(5,0) + DN_p2(6,0)*u_n_nodes(6,0) + DN_p2(7,0)*u_n_nodes(7,0) + DN_p2(8,0)*u_n_nodes(8,0) + DN_p2(9,0)*u_n_nodes(9,0)) + beta2_gauss*crRightHandSideVector19;
    const double crRightHandSideVector21 = DN_p2(0,1)*u_nodes(0,0) + DN_p2(1,1)*u_nodes(1,0) + DN_p2(2,1)*u_nodes(2,0) + DN_p2(3,1)*u_nodes(3,0) + DN_p2(4,1)*u_nodes(4,0) + DN_p2(5,1)*u_nodes(5,0) + DN_p2(6,1)*u_nodes(6,0) + DN_p2(7,1)*u_nodes(7,0) + DN_p2(8,1)*u_nodes(8,0) + DN_p2(9,1)*u_nodes(9,0);
    const double crRightHandSideVector22 = beta0_gauss*(DN_p2(0,1)*u_nn_nodes(0,0) + DN_p2(1,1)*u_nn_nodes(1,0) + DN_p2(2,1)*u_nn_nodes(2,0) + DN_p2(3,1)*u_nn_nodes(3,0) + DN_p2(4,1)*u_nn_nodes(4,0) + DN_p2(5,1)*u_nn_nodes(5,0) + DN_p2(6,1)*u_nn_nodes(6,0) + DN_p2(7,1)*u_nn_nodes(7,0) + DN_p2(8,1)*u_nn_nodes(8,0) + DN_p2(9,1)*u_nn_nodes(9,0)) + beta1_gauss*(DN_p2(0,1)*u_n_nodes(0,0) + DN_p2(1,1)*u_n_nodes(1,0) + DN_p2(2,1)*u_n_nodes(2,0) + DN_p2(3,1)*u_n_nodes(3,0) + DN_p2(4,1)*u_n_nodes(4,0) + DN_p2(5,1)*u_n_nodes(5,0) + DN_p2(6,1)*u_n_nodes(6,0) + DN_p2(7,1)*u_n_nodes(7,0) + DN_p2(8,1)*u_n_nodes(8,0) + DN_p2(9,1)*u_n_nodes(9,0)) + beta2_gauss*crRightHandSideVector21;
